def all_simple_paths(adj, s, d, limit=40):
    out = []
    stack = [(s, [s])]
    while stack and len(out) < limit:
        node, path = stack.pop()
        if node == d:
            out.append(path[:])
            continue
        for nxt in adj[node]:
            if nxt not in path:
                stack.append((nxt, path + [nxt]))
    return out


