        else:
            if repairs:
                events.append({'op': 'validate', 'id': rng.choice(repairs)})
    return events


def norm(answer):
    import json
    return json.loads(json.dumps(answer, sort_keys=True))


def run_case(topo, settings, events, verbose=False):
    stream = Stream({'topology': topo, 'settings': settings, 'events': events})
    mine = [stream.handle(e) for e in events]
    r = refmod.Ref(topo, settings)
    theirs = []
    for e in events:
        op = e['op']
        if op == 'patch':
            accepted = apply_patch_ref(r, e)
            theirs.append({'op': 'patch', 'accepted': accepted})
        elif op == 'routes':
            apply_routes_ref(r, e)
            theirs.append({'op': 'routes', 'accepted': True})
        elif op == 'repair':
            theirs.append(r.do_repair(e['id']))
        else:
            theirs.append(r.do_validate(e['id']))
    for i, (a, b) in enumerate(zip(mine, theirs)):
        if norm(a) != norm(b):
            print('MISMATCH at event', i, events[i])
            print('mine  ', norm(a))
            print('ref   ', norm(b))
            return False
    return True


def apply_patch_ref(r, ev):
    # reference trusts the generator: all patches are valid
    for s, d, v in ev['demands']:
        r.demands[(s, d)] = v
    for k, cell in ev['counters'].items():
        r.counters[k] = None if cell is None else cell['perturbed']
    return True


def apply_routes_ref(r, ev):
    plan = ev['paths']
    if plan is None:
        r.paths_present = False
        r.paths = {}
        return
    name_to_id = r.name_to_id
    entries = {}
    for sname, bundles in plan.items():
        for dname, opts in bundles.items():
            lst = []
            for o in opts:
                names = o['path']
                hops = tuple((name_to_id[names[i]], name_to_id[names[i + 1]]) for i in range(len(names) - 1))
                lst.append((hops, o['weight']))
            entries[(name_to_id[sname], name_to_id[dname])] = lst
    r.paths = entries
    r.paths_present = True


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    ok = 0
    for i in range(count):
        topo = rand_topology(rng)
        settings = rand_settings(rng)
        events = gen_events(rng, topo, settings, rng.randint(1, 12))
        if run_case(topo, settings, events):
            ok += 1
        else:
            print('case', i, 'topo', topo)
            print('settings', settings)
            print('events', events)
            return 1
    print('all %d cases matched' % ok)
    return 0


if __name__ == '__main__':
    sys.exit(main())
